_ED_P = 2 ** 255 - 19
_ED_Q = 2 ** 252 + 27742317777372353535851937790883648493
_ED_D = -121665 * pow(121666, _ED_P - 2, _ED_P) % _ED_P
_ED_I = pow(2, (_ED_P - 1) // 4, _ED_P)
def _ed_add(a, b):
    (x1, y1), (x2, y2) = a, b
    t = _ED_D * x1 * x2 * y1 * y2 % _ED_P
    return ((x1 * y2 + x2 * y1) * pow(1 + t, _ED_P - 2, _ED_P) % _ED_P,
            (y1 * y2 + x1 * x2) * pow(1 - t, _ED_P - 2, _ED_P) % _ED_P)
def _ed_mul(pt, e):
    r, q = (0, 1), pt
    while e:
        if e & 1: r = _ed_add(r, q)
        q = _ed_add(q, q); e >>= 1
    return r
def _ed_point(b32):
    y = int.from_bytes(b32, "little"); sign, y = y >> 255, y & ((1 << 255) - 1)
    if y >= _ED_P: return None
    xx = (y * y - 1) * pow(_ED_D * y * y + 1, _ED_P - 2, _ED_P) % _ED_P
    x = pow(xx, (_ED_P + 3) // 8, _ED_P)
    if (x * x - xx) % _ED_P: x = x * _ED_I % _ED_P
    if (x * x - xx) % _ED_P: return None
    if x & 1 != sign: x = _ED_P - x
    return (x, y)
_ED_B = (15112221349535400772501151409588531511454012693041857206046113283949847762202,
         46316835694926478169428394003475163141307993866256225615783033603165251855960)
def _ed25519_verify(pub, sig, msg):
    try:
        if len(pub) != 32 or len(sig) != 64: return False
        a, r = _ed_point(pub), _ed_point(sig[:32])
        s_ = int.from_bytes(sig[32:], "little")
        if a is None or r is None or s_ >= _ED_Q: return False
        h = int.from_bytes(hashlib.sha512(sig[:32] + pub + msg).digest(), "little") % _ED_Q
        return _ed_mul(_ED_B, s_) == _ed_add(r, _ed_mul(a, h))
    except Exception:
        return False

def _vt(v):
    try: return tuple(int(x) for x in str(v).split("."))
    except Exception: return (0,)

def _update():
    if globals().get("_SKIP_UPDATE") or os.environ.get("ABA_NO_UPDATE"):
        return False
    try:
        import json, time, urllib.request
        def get(name, limit):
            req = urllib.request.Request(_UPD_BASE + name + "?t=" + str(int(time.time())), headers={"User-Agent": "ABA-Timer"})
            with urllib.request.urlopen(req, timeout=5) as r:
                data = r.read(limit + 1)
            if len(data) > limit: raise ValueError("too big")
            return data
        man = json.loads(get("version.json", 20000).decode("utf-8"))
        ver, files = str(man["version"]), dict(man["files"])
        if _vt(ver) <= _vt(_LV): return False
        if set(files) - set(_SELF_NAMES) - {"hotbar_profiles.npz"}: return False
        here = os.path.dirname(os.path.abspath(__file__)); me = os.path.abspath(__file__)
        main = os.path.basename(me)
        self_key = main if main in files else next((n for n in _SELF_NAMES if n in files), None)
        if self_key is None: return False
        msg = ("ABAUPD1\n" + ver + "\n" + "\n".join(n + "=" + files[n] for n in sorted(files))).encode()
        if not _ed25519_verify(base64.b64decode(_UPD_PUB), base64.b64decode(man["sig"]), msg): return False
        print("ASTRAL: updating " + _LV + " -> " + ver + " ...", flush=True)
        want = [n for n in files if n == self_key or n == "hotbar_profiles.npz"]
        new = {}
        for n in want:
            data = get(n, 20000000)
            if hashlib.sha256(data).hexdigest() != files[n]: return False
            new[n] = data
        if ('_LV = "' + ver + '"').encode() not in new[self_key]: return False
        compile(new[self_key], self_key, "exec")
        done = []
        try:
            for n, data in new.items():
                path = me if n == self_key else os.path.join(here, n)
                if os.path.exists(path):
                    try:
                        import shutil; shutil.copyfile(path, path + ".bak")
                    except Exception: pass
                with open(path + ".new", "wb") as f: f.write(data)
                os.replace(path + ".new", path); done.append(path)
        except Exception:
            for path in done:
                try: os.replace(path + ".bak", path)
                except Exception: pass
            return False
        print("ASTRAL: updated to " + ver, flush=True)
        return True
    except Exception:
        return False

def _fail(text):
    try:
        import ctypes; ctypes.windll.user32.MessageBoxW(0, text, "ASTRAL", 0x10)
    except Exception:
        print(text)
    sys.exit(1)

def _load():
    if sys.gettrace() is not None or sys.getprofile() is not None:
        _fail("Debuggers and tracers are not allowed.")
    key = hashlib.sha256("".join(_P).encode()).digest()
    raw = base64.b85decode(_B.encode())
    salt, tag, ct = raw[:16], raw[16:32], raw[32:]
    if hashlib.sha256(key + salt + ct).digest()[:16] != tag:
        _fail("This file is damaged. Download the program again.")
    ks = b"".join(hashlib.sha256(key + salt + i.to_bytes(8, "big")).digest()
                  for i in range((len(ct) // 32) + 1))[:len(ct)]
    src = zlib.decompress(bytes(a ^ b for a, b in zip(ct, ks))).decode("utf-8")
    return compile(src, "astral", "exec")

def run(name="__main__"):
    g = {"__name__": name, "__file__": os.path.abspath(__file__), "__builtins__": __builtins__, "__doc__": None}
    code = _load()
    exec(code, g)
    return g

if __name__ == "__main__":
    if _update():
        import runpy
        runpy.run_path(os.path.abspath(__file__), init_globals={"_SKIP_UPDATE": True}, run_name="__main__")
    else:
        run()
